1	package registry
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"sort"
9		"strings"
10		"sync"
11		"time"
12	)
13	
14	// Registry 是一个已打开的本地登记册。同一目录同时只能被一个 Registry
15	// 独占打开（目录内 flock）；单个 Registry 的方法可被多个 goroutine
16	// 并发调用，所有状态变更与落盘在同一把互斥锁内一次完成。
17	type Registry struct {
18		dir    string
19		store  *store
20		state  *snapshot
21		mu     sync.Mutex
22		closed bool
23		// now 返回当前时间，到期判断以此为准；生产环境为 time.Now，测试可替换。
24		now func() time.Time
25	}
26	
27	// Create 在 dir 新建并打开一个空登记册。调用者通过 dir 指定本机数据
28	// 位置；目录不存在会被创建。目录中已存在登记册数据时返回错误，
29	// 已有的数据不会被覆盖。
30	func Create(dir string) (*Registry, error) {
31		if strings.TrimSpace(dir) == "" {
32			return nil, fmt.Errorf("%w: 数据目录不能为空", ErrInvalidArgument)
33		}
34		if err := os.MkdirAll(dir, dirMode); err != nil {
35			return nil, fmt.Errorf("registry: 无法创建数据目录: %w", err)
36		}
37		if _, err := os.Stat(dataFile(dir)); err == nil {
38			return nil, fmt.Errorf("%w: %s 已存在登记册数据，应用 Open 打开", ErrAlreadyExists, dir)
39		} else if !errors.Is(err, os.ErrNotExist) {
40			return nil, fmt.Errorf("registry: 无法访问数据目录: %w", err)
41		}
42		lock, err := acquireLock(dir)
43		if err != nil {
44			return nil, err
45		}
46		// 取锁后再确认一次，避免与另一个进程的 Create 竞争。
47		if _, err := os.Stat(dataFile(dir)); err == nil {
48			_ = releaseLock(lock)
49			return nil, fmt.Errorf("%w: %s 已存在登记册数据", ErrAlreadyExists, dir)
50		}
51		st := &store{dir: dir, lock: lock}
52		s := newSnapshot()
53		if err := st.save(s); err != nil {
54			_ = releaseLock(lock)
55			return nil, err
56		}
57		return &Registry{dir: dir, store: st, state: s, now: time.Now}, nil
58	}
59	
60	// Open 打开 dir 中的已有登记册。数据文件缺失视为空目录的新建场景，
61	// 应使用 Create；数据存在但无法读取或解析时返回包裹 ErrCorrupt 的
62	// 错误，不会被静默当成空登记册。
63	func Open(dir string) (*Registry, error) {
64		if strings.TrimSpace(dir) == "" {
65			return nil, fmt.Errorf("%w: 数据目录不能为空", ErrInvalidArgument)
66		}
67		if info, err := os.Stat(dir); err != nil {
68			return nil, fmt.Errorf("registry: 无法打开数据目录: %w", err)
69		} else if !info.IsDir() {
70			return nil, fmt.Errorf("%w: %s 不是目录", ErrInvalidArgument, dir)
71		}
72		lock, err := acquireLock(dir)
73		if err != nil {
74			return nil, err
75		}
76		// 数据文件不存在不是"空登记册"：明确报错，提示用 Create 新建，
77		// 绝不把无数据目录静默当成空登记册。
78		if _, err := os.Stat(dataFile(dir)); err != nil {
79			_ = releaseLock(lock)
80			if errors.Is(err, os.ErrNotExist) {
81				return nil, fmt.Errorf("%w: %s 中没有登记册数据，请用 Create 新建", ErrNotFound, dir)
82			}
83			return nil, fmt.Errorf("registry: 无法访问登记册数据: %w", err)
84		}
85		s, err := load(dir)
86		if err != nil {
87			_ = releaseLock(lock)
88			return nil, err
89		}
90		return &Registry{dir: dir, store: &store{dir: dir, lock: lock}, state: s, now: time.Now}, nil
91	}
92	
93	// Close 正常关闭登记册并释放独占锁。关闭后不能再调用其他方法。
94	func (r *Registry) Close() error {
95		r.mu.Lock()
96		defer r.mu.Unlock()
97		if r.closed {
98			return nil
99		}
100		r.closed = true
101		return releaseLock(r.store.lock)
102	}
103	
104	func releaseLock(f *os.File) error {
105		err := f.Close() // Close 同时释放 flock
106		if err != nil {
107			return fmt.Errorf("registry: 关闭登记册失败: %w", err)
108		}
109		return nil
110	}
111	
112	func (r *Registry) checkOpen() error {
113		if r.closed {
114			return fmt.Errorf("registry: 登记册已关闭")
115		}
116		return nil
117	}
118	
119	// commit 将当前状态原子落盘；落盘失败时以磁盘内容为准重新加载，
120	// 避免内存状态与已持久化状态不一致。
121	func (r *Registry) commit() error {
122		if err := r.store.save(r.state); err != nil {
123			if s, lerr := load(r.dir); lerr == nil {
124				r.state = s
125			}
126			return err
127		}
128		return nil
129	}
130	
131	// ---- 账户 ----
132	
133	// RegisterAccount 以唯一编号登记账户，登记后即为可用状态。
134	func (r *Registry) RegisterAccount(id, metadata string) error {
135		r.mu.Lock()
136		defer r.mu.Unlock()
137		if err := r.checkOpen(); err != nil {
138			return err
139		}
140		if strings.TrimSpace(id) == "" {
141			return fmt.Errorf("%w: 账户编号不能为空", ErrInvalidArgument)
142		}
143		if _, ok := r.state.Accounts[id]; ok {
144			return fmt.Errorf("%w: 账户 %s", ErrAlreadyExists, id)
145		}
146		r.state.Accounts[id] = account{ID: id, Metadata: metadata, Active: true}
147		return r.commit()
148	}
149	
150	// DeactivateAccount 停用账户。停用后其原有藏品与历史仍可查询，但不能
151	// 再发行、发起或接收新的转让；停用不影响已经落盘的任何记录。
152	func (r *Registry) DeactivateAccount(id string) error {
153		r.mu.Lock()
154		defer r.mu.Unlock()
155		if err := r.checkOpen(); err != nil {
156			return err
157		}
158		a, ok := r.state.Accounts[id]
159		if !ok {
160			return fmt.Errorf("%w: 账户 %s", ErrNotFound, id)
161		}
162		if !a.Active {
163			return nil // 停用是幂等的终态
164		}
165		a.Active = false
166		r.state.Accounts[id] = a
167		return r.commit()
168	}
169	
170	// GetAccount 查询账户；账户不存在时返回包裹 ErrNotFound 的错误。
171	func (r *Registry) GetAccount(id string) (Account, error) {
172		r.mu.Lock()
173		defer r.mu.Unlock()
174		if err := r.checkOpen(); err != nil {
175			return Account{}, err
176		}
177		a, ok := r.state.Accounts[id]
178		if !ok {
179			return Account{}, fmt.Errorf("%w: 账户 %s", ErrNotFound, id)
180		}
181		return Account{ID: a.ID, Metadata: a.Metadata, Active: a.Active}, nil
182	}
183	
184	// ---- 系列 ----
185	
186	// CreateSeries 登记一个系列，记录创建账户与文字元数据。创建账户必须
187	// 已登记且可用；后续只有该账户能发行该系列的藏品或封存该系列。
188	func (r *Registry) CreateSeries(id, creatorID, metadata string) error {
189		r.mu.Lock()
190		defer r.mu.Unlock()
191		if err := r.checkOpen(); err != nil {
192			return err
193		}
194		if strings.TrimSpace(id) == "" {
195			return fmt.Errorf("%w: 系列编号不能为空", ErrInvalidArgument)
196		}
197		creator, ok := r.state.Accounts[creatorID]
198		if !ok {
199			return fmt.Errorf("%w: 创建账户 %s", ErrNotFound, creatorID)
200		}
201		if !creator.Active {
202			return fmt.Errorf("%w: 创建账户 %s", ErrAccountInactive, creatorID)
203		}
204		if _, ok := r.state.Series[id]; ok {
205			return fmt.Errorf("%w: 系列 %s", ErrAlreadyExists, id)
206		}
207		r.state.Series[id] = series{ID: id, CreatorID: creatorID, Metadata: metadata}
208		return r.commit()
209	}
210	
211	// SealSeries 封存系列。只有系列创建账户可以封存；封存后不能继续发行，
212	// 已发行藏品仍可转让，且封存不能撤销。
213	func (r *Registry) SealSeries(seriesID, operator string) error {
214		r.mu.Lock()
215		defer r.mu.Unlock()
216		if err := r.checkOpen(); err != nil {
217			return err
218		}
219		s, ok := r.state.Series[seriesID]
220		if !ok {
221			return fmt.Errorf("%w: 系列 %s", ErrNotFound, seriesID)
222		}
223		if s.CreatorID != operator {
224			return fmt.Errorf("%w: 只有创建账户 %s 可以封存系列 %s", ErrForbidden, s.CreatorID, seriesID)
225		}
226		if s.Sealed {
227			return nil // 封存不可撤销，重复封存视为已处于封存态
228		}
229		s.Sealed = true
230		r.state.Series[seriesID] = s
231		return r.commit()
232	}
233	
234	// GetSeries 查询系列；不存在时返回包裹 ErrNotFound 的错误。
235	func (r *Registry) GetSeries(id string) (Series, error) {
236		r.mu.Lock()
237		defer r.mu.Unlock()
238		if err := r.checkOpen(); err != nil {
239			return Series{}, err
240		}
241		s, ok := r.state.Series[id]
242		if !ok {
243			return Series{}, fmt.Errorf("%w: 系列 %s", ErrNotFound, id)
244		}
245		return Series{ID: s.ID, CreatorID: s.CreatorID, Metadata: s.Metadata, Sealed: s.Sealed}, nil
246	}
247	
248	// ---- 发行 ----
249	
250	func (req IssueRequest) validatePresent() error {
251		missing := []string{}
252		if strings.TrimSpace(req.Operator) == "" {
253			missing = append(missing, "operator")
254		}
255		if strings.TrimSpace(req.Reason) == "" {
256			missing = append(missing, "reason")
257		}
258		if strings.TrimSpace(req.RequestID) == "" {
259			missing = append(missing, "request_id")
260		}
261		if strings.TrimSpace(req.ItemID) == "" {
262			missing = append(missing, "item_id")
263		}
264		if strings.TrimSpace(req.SeriesID) == "" {
265			missing = append(missing, "series_id")
266		}
267		if strings.TrimSpace(req.BatchNo) == "" {
268			missing = append(missing, "batch_no")
269		}
270		if strings.TrimSpace(req.HolderID) == "" {
271			missing = append(missing, "holder_id")
272		}
273		if len(missing) > 0 {
274			return fmt.Errorf("%w: 发行请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
275		}
276		return nil
277	}
278	
279	func issueParamsSig(req IssueRequest) string {
280		b, _ := json.Marshal(struct {
281			Kind     string `json:"kind"`
282			ItemID   string `json:"item_id"`
283			SeriesID string `json:"series_id"`
284			BatchNo  string `json:"batch_no"`
285			Metadata string `json:"metadata"`
286			HolderID string `json:"holder_id"`
287			Reason   string `json:"reason"`
288		}{"issue", req.ItemID, req.SeriesID, req.BatchNo, req.Metadata, req.HolderID, req.Reason})
289		return string(b)
290	}
291	
292	// Issue 发行一件藏品。成功后持有版本为 1，初始持有人为 req.HolderID。
293	// 操作者必须是系列创建账户且可用，初始持有人必须已登记且可用，系列未
294	// 封存，藏品编号从未使用过。同一 (操作者, 请求号) 且业务参数相同的
295	// 重复提交返回首次结果；参数不同返回 ErrRequestConflict。
296	func (r *Registry) Issue(req IssueRequest) (IssueResult, error) {
297		if err := req.validatePresent(); err != nil {
298			return IssueResult{}, err
299		}
300		r.mu.Lock()
301		defer r.mu.Unlock()
302		if err := r.checkOpen(); err != nil {
303			return IssueResult{}, err
304		}
305	
306		key := requestKey(req.Operator, req.RequestID)
307		sig := issueParamsSig(req)
308		if prev, ok := r.state.Requests[key]; ok {
309			return r.replayIssue(prev, sig)
310		}
311	
312		bizErr := r.checkIssue(req)
313		if bizErr != nil {
314			if !isValidationErr(bizErr) {
315				// 状态类业务拒绝（封存、停用、无权、编号已用等）占用请求号并
316				// 落盘：相同参数重提永远返回这一次拒绝，即使状态后来变化。
317				r.state.Requests[key] = request{
318					Operator: req.Operator, RequestID: req.RequestID, Kind: "issue",
319					Params: sig, Rejected: true, Reason: errCode(bizErr),
320					ItemID: req.ItemID,
321				}
322				_ = r.commit()
323			}
324			// 校验类错误（引用不存在等）不占用请求号，也不改变任何状态。
325			return IssueResult{ItemID: req.ItemID, Err: bizErr}, bizErr
326		}
327	
328		seq := r.state.NextSeq + 1
329		r.state.NextSeq = seq
330		r.state.Items[req.ItemID] = item{
331			ID: req.ItemID, SeriesID: req.SeriesID, BatchNo: req.BatchNo,
332			Metadata: req.Metadata, IssuedTxID: seq,
333		}
334		r.state.Holdings[req.ItemID] = holding{ItemID: req.ItemID, OwnerID: req.HolderID, Version: 1}
335		r.state.History = append(r.state.History, historyEntry{
336			Seq: seq, Kind: "issue", ItemID: req.ItemID, Operator: req.Operator,
337			Reason: req.Reason, RequestID: req.RequestID,
338			FromID: "", ToID: req.HolderID, FromVersion: 0, ToVersion: 1,
339		})
340		r.state.Requests[key] = request{
341			Operator: req.Operator, RequestID: req.RequestID, Kind: "issue",
342			Params: sig, ItemID: req.ItemID, ToID: req.HolderID, Version: 1, TxSeq: seq,
343		}
344		if err := r.commit(); err != nil {
345			return IssueResult{}, err
346		}
347		return IssueResult{ItemID: req.ItemID, OwnerID: req.HolderID, Version: 1, TxSeq: seq}, nil
348	}
349	
350	func (r *Registry) checkIssue(req IssueRequest) error {
351		op, ok := r.state.Accounts[req.Operator]
352		if !ok {
353			return fmt.Errorf("%w: 操作者账户 %s", ErrNotFound, req.Operator)
354		}
355		if !op.Active {
356			return fmt.Errorf("%w: 操作者账户 %s", ErrAccountInactive, req.Operator)
357		}
358		s, ok := r.state.Series[req.SeriesID]
359		if !ok {
360			return fmt.Errorf("%w: 系列 %s", ErrNotFound, req.SeriesID)
361		}
362		if s.Sealed {
363			return fmt.Errorf("%w: 系列 %s", ErrSeriesSealed, req.SeriesID)
364		}
365		if s.CreatorID != req.Operator {
366			return fmt.Errorf("%w: 只有系列创建账户 %s 可以发行", ErrForbidden, s.CreatorID)
367		}
368		if _, ok := r.state.Items[req.ItemID]; ok {
369			return fmt.Errorf("%w: 藏品编号 %s 已被使用", ErrAlreadyExists, req.ItemID)
370		}
371		h, ok := r.state.Accounts[req.HolderID]
372		if !ok {
373			return fmt.Errorf("%w: 初始持有人账户 %s", ErrNotFound, req.HolderID)
374		}
375		if !h.Active {
376			return fmt.Errorf("%w: 初始持有人账户 %s", ErrAccountInactive, req.HolderID)
377		}
378		return nil
379	}
380	
381	func (r *Registry) replayIssue(prev request, sig string) (IssueResult, error) {
382		if prev.Kind != "issue" || prev.Params != sig {
383			return IssueResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
384				ErrRequestConflict, prev.Operator, prev.RequestID)
385		}
386		res := IssueResult{ItemID: prev.ItemID, OwnerID: prev.ToID, Version: prev.Version,
387			TxSeq: prev.TxSeq, Replayed: true}
388		if prev.Rejected {
389			res.Err = codeErr(prev.Reason)
390			return res, res.Err
391		}
392		return res, nil
393	}
394	
395	// ---- 转让 ----
396	
397	func (req TransferRequest) validatePresent() error {
398		missing := []string{}
399		if strings.TrimSpace(req.Operator) == "" {
400			missing = append(missing, "operator")
401		}
402		if strings.TrimSpace(req.Reason) == "" {
403			missing = append(missing, "reason")
404		}
405		if strings.TrimSpace(req.RequestID) == "" {
406			missing = append(missing, "request_id")
407		}
408		if strings.TrimSpace(req.ItemID) == "" {
409			missing = append(missing, "item_id")
410		}
411		if strings.TrimSpace(req.ExpectedOwner) == "" {
412			missing = append(missing, "expected_owner")
413		}
414		if strings.TrimSpace(req.ToID) == "" {
415			missing = append(missing, "to_id")
416		}
417		if req.ExpectedVer <= 0 {
418			missing = append(missing, "expected_version")
419		}
420		if len(missing) > 0 {
421			return fmt.Errorf("%w: 转让请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
422		}
423		if req.Price < 0 {
424			return fmt.Errorf("%w: 成交价款 %d 不能为负", ErrInvalidArgument, req.Price)
425		}
426		return nil
427	}
428	
429	func transferParamsSig(req TransferRequest) string {
430		// Price 用 omitempty：价款为 0 时签名与引入价款前的旧格式一致，
431		// 旧登记册中落盘的请求仍可按原参数回放；改价则签名不同、按请求号
432		// 冲突拒绝。
433		b, _ := json.Marshal(struct {
434			Kind          string `json:"kind"`
435			ItemID        string `json:"item_id"`
436			ExpectedOwner string `json:"expected_owner"`
437			ExpectedVer   int64  `json:"expected_version"`
438			ToID          string `json:"to_id"`
439			Price         int64  `json:"price,omitempty"`
440			Reason        string `json:"reason"`
441		}{"transfer", req.ItemID, req.ExpectedOwner, req.ExpectedVer, req.ToID, req.Price, req.Reason})
442		return string(b)
443	}
444	
445	// Transfer 由当前持有人发起转让。接收人必须已登记、可用且不同于当前
446	// 持有人；请求必须给出期望持有人与期望版本，藏品不存在或持有人/版本
447	// 不符时返回业务拒绝且不改变任何状态。成交价款（分）由持有人填写，
448	// 非负、未填按 0；成功时按所属系列的版税规则一次落盘各收款账户的
449	// 应付明细与归转让前持有人的余款。同一 (操作者, 请求号) 的相同
450	// 请求重复提交（即使藏品后来已易手）返回首次结果。
451	func (r *Registry) Transfer(req TransferRequest) (TransferResult, error) {
452		if err := req.validatePresent(); err != nil {
453			return TransferResult{}, err
454		}
455		r.mu.Lock()
456		defer r.mu.Unlock()
457		if err := r.checkOpen(); err != nil {
458			return TransferResult{}, err
459		}
460	
461		key := requestKey(req.Operator, req.RequestID)
462		sig := transferParamsSig(req)
463		if prev, ok := r.state.Requests[key]; ok {
464			return r.replayTransfer(prev, sig)
465		}
466	
467		bizErr := r.checkTransfer(req)
468		if bizErr != nil {
469			if !isValidationErr(bizErr) {
470				// 状态类业务拒绝（持有人/版本不符、账户停用、收发同人等）
471				// 占用请求号并落盘，相同参数重提永远返回这一次拒绝。
472				r.state.Requests[key] = request{
473					Operator: req.Operator, RequestID: req.RequestID, Kind: "transfer",
474					Params: sig, Rejected: true, Reason: errCode(bizErr),
475					ItemID: req.ItemID,
476				}
477				_ = r.commit()
478			}
479			// 藏品或账户不存在等校验错误不占用请求号，也不改变持有或历史。
480			return TransferResult{ItemID: req.ItemID, Err: bizErr}, bizErr
481		}
482	
483		h := r.state.Holdings[req.ItemID]
484		seq := r.state.NextSeq + 1
485		r.state.NextSeq = seq
486		from := h.OwnerID
487		fromVer := h.Version
488		h.OwnerID = req.ToID
489		h.Version = fromVer + 1
490		r.state.Holdings[req.ItemID] = h
491		r.state.History = append(r.state.History, historyEntry{
492			Seq: seq, Kind: "transfer", ItemID: req.ItemID, Operator: req.Operator,
493			Reason: req.Reason, RequestID: req.RequestID,
494			FromID: from, ToID: req.ToID, FromVersion: fromVer, ToVersion: fromVer + 1,
495		})
496		// 版税应付与持有变化、历史、请求结果在同一临界区内一次落盘；
497		// 余款归转让前持有人。
498		it := r.state.Items[req.ItemID]
499		royalty := newRoyaltyRec(seq, req.ItemID, it.SeriesID, req.Price,
500			r.state.Series[it.SeriesID].Royalty, from)
501		r.state.Royalties[seq] = royalty
502		r.state.Requests[key] = request{
503			Operator: req.Operator, RequestID: req.RequestID, Kind: "transfer",
504			Params: sig, ItemID: req.ItemID, FromID: from, ToID: req.ToID,
505			Version: fromVer + 1, TxSeq: seq,
506		}
507		if err := r.commit(); err != nil {
508			return TransferResult{}, err
509		}
510		return TransferResult{ItemID: req.ItemID, FromID: from, ToID: req.ToID,
511			Version: fromVer + 1, TxSeq: seq,
512			Price: royalty.Price, Payables: publicPayables(royalty.Payees),
513			Remainder: royalty.Remainder}, nil
514	}
