588		}
589		if strings.TrimSpace(req.Reason) == "" {
590			missing = append(missing, "reason")
591		}
592		if strings.TrimSpace(req.RequestID) == "" {
593			missing = append(missing, "request_id")
594		}
595		if strings.TrimSpace(req.AuthID) == "" {
596			missing = append(missing, "auth_id")
597		}
598		if strings.TrimSpace(req.ItemID) == "" {
599			missing = append(missing, "item_id")
600		}
601		if strings.TrimSpace(req.TrusteeID) == "" {
602			missing = append(missing, "trustee_id")
603		}
604		if strings.TrimSpace(req.ToID) == "" {
605			missing = append(missing, "to_id")
606		}
607		if strings.TrimSpace(req.ExpectedOwner) == "" {
608			missing = append(missing, "expected_owner")
609		}
610		if req.ExpectedVer <= 0 {
611			missing = append(missing, "expected_version")
612		}
613		if req.ExpiresAt.IsZero() {
614			missing = append(missing, "expires_at")
615		}
616		if len(missing) > 0 {
617			return fmt.Errorf("%w: 创建授权请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
618		}
619		if req.Price < 0 {
620			return fmt.Errorf("%w: 成交价款 %d 不能为负", ErrInvalidArgument, req.Price)
621		}
622		return nil
623	}
