625	func createAuthzParamsSig(req CreateAuthorizationRequest) string {
626		// Price 用 omitempty：价款为 0 时签名与旧格式一致，旧授权创建请求
627		// 仍可回放；改价则按请求号冲突拒绝。
628		b, _ := json.Marshal(struct {
629			Kind          string `json:"kind"`
630			AuthID        string `json:"auth_id"`
631			ItemID        string `json:"item_id"`
632			TrusteeID     string `json:"trustee_id"`
633			ToID          string `json:"to_id"`
634			ExpectedOwner string `json:"expected_owner"`
635			ExpectedVer   int64  `json:"expected_version"`
636			ExpiresAt     string `json:"expires_at"`
637			Price         int64  `json:"price,omitempty"`
638			Reason        string `json:"reason"`
639		}{"auth_create", req.AuthID, req.ItemID, req.TrusteeID, req.ToID,
640			req.ExpectedOwner, req.ExpectedVer,
641			req.ExpiresAt.UTC().Format(time.RFC3339Nano), req.Price, req.Reason})
642		return string(b)
643	}
